[
  {
    "version": "v0.9",
    "createSurface": {
      "surfaceId": "sp500-vs-gold-surface",
      "catalogId": "https://genui.local/specification/v0_9/standard_catalog.json"
    }
  },
  {
    "version": "v0.9",
    "updateDataModel": {
      "surfaceId": "sp500-vs-gold-surface",
      "value": {
        "performanceData": [
          {
            "asset": "S&P 500",
            "growth": "+175%",
            "volatility": "Higher"
          },
          {
            "asset": "Gold",
            "growth": "+420%",
            "volatility": "Moderate"
          }
        ]
      }
    }
  },
  {
    "version": "v0.9",
    "updateComponents": {
      "surfaceId": "sp500-vs-gold-surface",
      "components": [
        {
          "id": "root",
          "type": "Column",
          "properties": {
            "spacing": "medium",
            "children": [
              {
                "id": "assumptions_card",
                "type": "Card",
                "properties": {
                  "child": {
                    "id": "assumptions_text",
                    "type": "TextBlock",
                    "properties": {
                      "text": "Assumptions: All data provided is illustrative and based on general historical trends for the specified period (January 1, 2000, to December 31, 2020). Actual returns and volatility may vary based on specific data sources and calculation methodologies.",
                      "size": "small",
                      "isItalic": true
                    }
                  }
                }
              },
              {
                "id": "summary_card",
                "type": "Card",
                "properties": {
                  "header": {
                    "id": "summary_header",
                    "type": "Header",
                    "properties": {
                      "title": "Summary of Performance (EXAMPLE DATA)"
                    }
                  },
                  "child": {
                    "id": "summary_column",
                    "type": "Column",
                    "properties": {
                      "spacing": "medium",
                      "children": [
                        {
                          "id": "summary_sp500",
                          "type": "TextBlock",
                          "properties": {
                            "text": "**S&P 500:** The S&P 500, representing a broad measure of U.S. equities, navigated through two major bear markets (dot-com bust and 2008 financial crisis) before a strong bull run. Its total percentage growth (price return, excluding dividends) was approximately **+175%**."
                          }
                        },
                        {
                          "id": "summary_gold",
                          "type": "TextBlock",
                          "properties": {
                            "text": "**Gold:** Often considered a safe-haven asset, Gold saw substantial appreciation, particularly during periods of economic uncertainty and low interest rates. Its total percentage growth was approximately **+420%**."
                          }
                        }
                      ]
                    }
                  }
                }
              },
              {
                "id": "volatility_card",
                "type": "Card",
                "properties": {
                  "header": {
                    "id": "volatility_header",
                    "type": "Header",
                    "properties": {
                      "title": "Volatility Comparison (EXAMPLE DATA)"
                    }
                  },
                  "child": {
                    "id": "volatility_column",
                    "type": "Column",
                    "properties": {
                      "spacing": "medium",
                      "children": [
                        {
                          "id": "volatility_sp500",
                          "type": "TextBlock",
                          "properties": {
                            "text": "**S&P 500:** Experienced significant periods of high volatility, particularly during market downturns like the dot-com bust (2000-2002), the Global Financial Crisis (2008-2009), and the COVID-19 crash (2020). The S&P 500 generally exhibited higher volatility over this period."
                          }
                        },
                        {
                          "id": "volatility_gold",
                          "type": "TextBlock",
                          "properties": {
                            "text": "**Gold:** While Gold can also be volatile, it often demonstrated a lower correlation with equities and sometimes acted as a hedge during equity market downturns. However, it also had its own periods of significant price swings, especially after major rallies."
                          }
                        },
                        {
                          "id": "volatility_conclusion",
                          "type": "TextBlock",
                          "properties": {
                            "text": "**Conclusion on Volatility:** The S&P 500 generally had higher volatility due to the more pronounced and frequent large drawdowns it experienced during this specific timeframe."
                          }
                        }
                      ]
                    }
                  }
                }
              },
              {
                "id": "overview_card",
                "type": "Card",
                "properties": {
                  "header": {
                    "id": "overview_header",
                    "type": "Header",
                    "properties": {
                      "title": "Performance and Volatility Overview (EXAMPLE DATA)"
                    }
                  },
                  "child": {
                    "id": "overview_list",
                    "type": "List",
                    "properties": {
                      "data": "{{dataModel.performanceData}}",
                      "template": {
                        "id": "overview_row_template",
                        "type": "Row",
                        "properties": {
                          "children": [
                            {
                              "id": "asset_name",
                              "type": "TextBlock",
                              "properties": {
                                "text": "{{item.asset}}",
                                "weight": "bold",
                                "horizontalAlignment": "start",
                                "width": "1fr"
                              }
                            },
                            {
                              "id": "asset_growth",
                              "type": "TextBlock",
                              "properties": {
                                "text": "{{item.growth}}",
                                "horizontalAlignment": "center",
                                "width": "1fr"
                              }
                            },
                            {
                              "id": "asset_volatility",
                              "type": "TextBlock",
                              "properties": {
                                "text": "{{item.volatility}}",
                                "horizontalAlignment": "end",
                                "width": "1fr"
                              }
                            }
                          ]
                        }
                      }
                    }
                  }
                }
              },
              {
                "id": "crashes_card",
                "type": "Card",
                "properties": {
                  "header": {
                    "id": "crashes_header",
                    "type": "Header",
                    "properties": {
                      "title": "Significant Market Crashes (2000 - 2020)"
                    }
                  },
                  "child": {
                    "id": "crashes_list",
                    "type": "List",
                    "properties": {
                      "children": [
                        {
                          "id": "crash_1",
                          "type": "Column",
                          "properties": {
                            "children": [
                              {
                                "id": "crash_1_title",
                                "type": "TextBlock",
                                "properties": {
                                  "text": "**1. Dot-com Bubble Burst (2000-2002)**",
                                  "weight": "bold"
                                }
                              },
                              {
                                "id": "crash_1_desc",
                                "type": "TextBlock",
                                "properties": {
                                  "text": "The full impact of the collapse of the technology and internet bubble was deeply felt in the early 2000s, leading to a significant bear market for the S&P 500."
                                }
                              }
                            ]
                          }
                        },
                        {
                          "id": "crash_2",
                          "type": "Column",
                          "properties": {
                            "children": [
                              {
                                "id": "crash_2_title",
                                "type": "TextBlock",
                                "properties": {
                                  "text": "**2. Global Financial Crisis (2008)**",
                                  "weight": "bold"
                                }
                              },
                              {
                                "id": "crash_2_desc",
                                "type": "TextBlock",
                                "properties": {
                                  "text": "Triggered by the subprime mortgage crisis, this led to a severe worldwide economic recession and one of the largest stock market crashes in history, with the S&P 500 dropping over 50% from its peak."
                                }
                              }
                            ]
                          }
                        },
                        {
                          "id": "crash_3",
                          "type": "Column",
                          "properties": {
                            "children": [
                              {
                                "id": "crash_3_title",
                                "type": "TextBlock",
                                "properties": {
                                  "text": "**3. COVID-19 Market Crash (Early 2020)**",
                                  "weight": "bold"
                                }
                              },
                              {
                                "id": "crash_3_desc",
                                "type": "TextBlock",
                                "properties": {
                                  "text": "A rapid and severe global stock market decline in February-March 2020, caused by the emerging COVID-19 pandemic and the resulting economic lockdowns and uncertainty."
                                }
                              }
                            ]
                          }
                        }
                      ]
                    }
                  }
                }
              },
              {
                "id": "actions_divider",
                "type": "Divider"
              },
              {
                "id": "actions_title",
                "type": "TextBlock",
                "properties": {
                  "text": "Quick Actions",
                  "weight": "bold",
                  "size": "large"
                }
              },
              {
                "id": "actions_row",
                "type": "Row",
                "properties": {
                  "spacing": "medium",
                  "children": [
                    {
                      "id": "sp500_button",
                      "type": "Button",
                      "properties": {
                        "label": "Learn more about S&P 500",
                        "action": {
                          "type": "functionCall",
                          "call": "openUrl",
                          "arguments": {
                            "url": "https://www.spglobal.com/spdji/en/indices/equity/sp-500/"
                          }
                        }
                      }
                    },
                    {
                      "id": "gold_button",
                      "type": "Button",
                      "properties": {
                        "label": "Explore Gold as an investment",
                        "action": {
                          "type": "functionCall",
                          "call": "openUrl",
                          "arguments": {
                            "url": "https://www.gold.org/"
                          }
                        }
                      }
                    }
                  ]
                }
              }
            ]
          }
        }
      ]
    }
  }
]
